import java.util.*

fun main() {
    val pq = PriorityQueue<Int>()
    pq.add(5); pq.add(1); pq.add(3); pq.add(4); pq.add(2)
    println(pq)
    println(pq.poll() to pq.peek() to pq.size)
    println(pq)
    pq.remove(4)
    println(pq)
    val pq2 = PriorityQueue<String>(compareByDescending { it.length })
    pq2.addAll(listOf("a", "ccc", "bb"))
    println(pq2.poll())
    val pq3 = PriorityQueue(listOf(9, 4, 7, 1, 8))
    println(pq3.toList())
    val order = ArrayList<Int>()
    while (pq3.isNotEmpty()) order.add(pq3.poll()!!)
    println(order)
    val tm = TreeMap<String, Int>()
    tm["b"] = 2; tm["a"] = 1; tm["d"] = 4
    println(tm.firstKey() to tm.lastKey())
    println(tm.floorKey("c") to tm.ceilingKey("c"))
    println(tm.headMap("c"))
    println(tm.descendingMap())
    val ll = LinkedList<Int>()
    ll.add(1); ll.addFirst(0); ll.addLast(2)
    println(ll)
    println(ll.removeFirst() + ll.removeLast())
    ll.push(9)
    println(ll.peek() to ll.pop() to ll.size)
    val q = LinkedList<String>()
    q.offer("x"); q.offer("y")
    println(q.poll() + q.poll() + q.poll())
    val al = ArrayList<Int>(listOf(3, 1, 2))
    Collections.sort(al)
    println(al)
    Collections.reverse(al)
    println(al)
    println(Collections.max(al) + Collections.min(al))
    println(Collections.emptyList<Int>().size)
    println(Collections.unmodifiableList(al))
    Collections.swap(al, 0, 2)
    println(al)
    Collections.sort(al, Collections.reverseOrder())
    println(al)
    println(Collections.nCopies(3, "ab"))
    println(Collections.frequency(listOf(1, 2, 1), 1))
    val sh = ArrayList((1..10).toList())
    Collections.shuffle(sh, java.util.Random(42))
    println(sh)
    println(Arrays.toString(intArrayOf(1, 2)))
    println(Arrays.toString(arrayOf("a", "b")))
    println(Arrays.asList(1, 2, 3))
    println(Arrays.equals(intArrayOf(1), intArrayOf(1)))
    val ia = intArrayOf(3, 1, 2)
    Arrays.sort(ia)
    println(ia.toList())
    println(Arrays.hashCode(intArrayOf(1, 2)))
    println(Arrays.deepToString(arrayOf(intArrayOf(1), intArrayOf(2, 3))))
    val fa = IntArray(3)
    Arrays.fill(fa, 7)
    println(Arrays.toString(Arrays.copyOf(fa, 5)))
    println(Objects.equals(null, null) to Objects.hash(1, 2))
    println(Objects.requireNonNull("x"))
    println(Objects.toString(null) + Objects.hashCode(null) + Objects.isNull(null))
    val sj = StringJoiner(", ", "{", "}")
    sj.add("a").add("b")
    println(sj)
    println(StringJoiner("-").setEmptyValue("EMPTY"))
    val st = Stack<Int>()
    st.push(1); st.push(2)
    println(st.peek() to st.pop() to st.size to st.empty())
    val r = java.util.Random(12345)
    println(r.nextInt())
    println(r.nextInt(100))
    println(r.nextLong())
    println(r.nextDouble())
    println(r.nextBoolean())
    println(r.nextInt(5, 10))
    println(r.nextGaussian())
    println(r.nextFloat())
    println(Comparator.naturalOrder<Int>().compare(1, 2))
    println(Comparator.comparing<String, Int> { it.length }.compare("a", "bb"))
    println(listOf("bb", "a", "ccc").sortedWith(Comparator.comparingInt<String> { it.length }.reversed()))
    println(listOf(3, 1, 2).sortedWith(Comparator.reverseOrder()))
}
